function r(t){return`<span class="sci-math sci-math--block">${t}</span>`}function c(t){return`<span class="sci-math">${t}</span>`}function o(t){return`<table class="sci-vars"><tbody>${t.map(([s,a])=>`<tr><td>${c(s)}</td><td>${a}</td></tr>`).join("")}</tbody></table>`}function d(t){return`<p class="sci-cite">${t}</p>`}function l(t,s){return`<table class="sci-data"><thead><tr>${t.map(a=>`<th>${a}</th>`).join("")}</tr></thead><tbody>${s.map(a=>`<tr>${a.map(n=>`<td>${n}</td>`).join("")}</tr>`).join("")}</tbody></table>`}function p(t,s,a,n){return`<div class="les-concept"><h3 class="les-concept__name">${t}</h3><div class="les-concept__body">${n==="advanced"?a:s}</div></div>`}function u(t){return`<div class="les-analogy"><span class="les-analogy__icon">&#128161;</span>${t}</div>`}function y(t){return`<div class="les-key-idea"><span class="les-key-idea__icon">&#9733;</span>${t}</div>`}function $(t,s){return`<div class="sci-try"><div class="sci-try__title">${t}</div>${s}</div>`}function v(t,s){return`<div class="sci-try__row">${t}${s}</div>`}function _(t,s){return`<div class="sci-try__output">${s}<span class="sci-try__value" id="${t}"></span></div>`}export{r as a,c as b,o as c,d,l as e,p as f,u as g,y as h,$ as i,v as j,_ as k};
